import{E as e}from"./index-CGqiu-qG.js";import{t}from"./SEOTitle-B4oHtgSm.js";import{t as n}from"./LegalLayout-VJL1GdIs.js";var r=e();function i(){return(0,r.jsxs)(n,{title:`Data Processing Agreement`,lastUpdated:`August 15, 2026`,children:[(0,r.jsx)(t,{title:`Data Processing Agreement`}),(0,r.jsx)(`p`,{className:`text-lg text-gray-600 mb-8 leading-relaxed`,children:`This Data Processing Agreement (“DPA”) forms part of the agreement between Selorah Health Limited (“Processor”, “Selorah”, “we”) and the institutional customer (“Controller”, “you”) that uses Selorah hospital, research, or insurer portals to process personal data. It applies where Selorah processes personal data on your documented instructions.`}),(0,r.jsx)(`p`,{className:`text-sm text-gray-500 mb-12`,children:`Estimated reading time: about 7 minutes.`}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`1. Definitions`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`“Personal Data”, “Processing”, “Controller”, “Processor”, “Data Subject”, and “Supervisory Authority” have meanings consistent with the Nigeria Data Protection Act and, where relevant, analogous terms under other applicable privacy laws. “Services” means the Selorah products described in your order or subscription. “Subprocessor” means any third party engaged by Selorah to process Personal Data on behalf of the Controller.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`2. Roles of the Parties`}),(0,r.jsx)(`p`,{className:`text-gray-600 mb-4`,children:`For institutional use cases (hospital directory, controlled access to patient records via tokens, research cohorts under your protocol), you determine the purposes and means of Processing as Controller. Selorah processes Personal Data only to provide the Services and on your documented instructions, unless required by law to act otherwise.`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`For Selorah’s own account administration, billing, security, and product improvement regarding institutional users’ staff accounts, Selorah may act as an independent controller as described in the Privacy Policy.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`3. Scope, Nature, and Purpose`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Processing includes storage, retrieval, transmission, display, and deletion of Personal Data uploaded or generated in the Services, including health-related records, identifiers (such as patient NIN where stored), access logs, and QR token metadata. The purpose is to deliver secure health-data workflows you configure, not for Selorah’s independent marketing of data subjects’ health information.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`4. Duration`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Processing continues for the term of your agreement with Selorah and any post-termination retention required to wind down the Services, export data, or meet legal obligations, after which Personal Data under this DPA is deleted or returned per Section 12.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`5. Controller Instructions`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Your instructions are documented in the product configuration, APIs, and written agreements. Selorah will inform you if an instruction appears to infringe applicable data protection law (unless legally prohibited). Additional instructions must be agreed in writing and may require changes to fees or timelines.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`6. Confidentiality`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Selorah ensures personnel authorized to process Personal Data are bound by confidentiality obligations and receive appropriate training on handling health and identity data.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`7. Security Measures`}),(0,r.jsx)(`p`,{className:`text-gray-600 mb-4`,children:`Taking into account the state of the art, costs, and risk, Selorah implements measures such as: encryption in transit; access controls and authentication; environment separation; logging and monitoring; vulnerability management; and backup processes. Details may be provided under NDA upon reasonable request.`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`You are responsible for securing credentials issued to your staff and for lawful collection of patient data before upload or share.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`8. Subprocessors`}),(0,r.jsx)(`p`,{className:`text-gray-600 mb-4`,children:`You authorize Selorah to engage Subprocessors for infrastructure, authentication, storage, email, and similar functions. Selorah will impose data-protection obligations no less protective than those in this DPA. A current list of core subprocessors is available on request.`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Selorah will provide notice of material Subprocessor changes where required, and you may object on reasonable data-protection grounds. If objection cannot be resolved, you may terminate the affected Services as your sole remedy.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`9. International Transfers`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Where Personal Data is transferred across borders, Selorah will ensure an appropriate transfer mechanism is in place (contractual clauses, adequacy, or other lawful tools). You authorize such transfers as needed to operate the Services.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`10. Assistance with Data Subject Rights`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Taking into account the nature of Processing, Selorah will assist you with reasonable requests to respond to data subject rights (access, correction, deletion, restriction, portability, objection) by providing self-service tools where available and technical support for complex requests. You remain responsible for verifying the requester’s identity and deciding the response.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`11. Breach Notification`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`After becoming aware of a Personal Data breach affecting Controller data, Selorah will notify you without undue delay and provide information reasonably available to help you meet your notification duties. Notification is not an admission of fault. The parties will cooperate on investigation and mitigation.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`12. Return or Deletion`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Upon termination of the Services, at your choice Selorah will delete or return Controller Personal Data, unless retention is required by law or needed for residual security logs under reduced access. Certification of deletion may be provided upon written request after completion of standard purge cycles.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`13. Audits`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Upon reasonable written notice, no more than once annually (unless a supervisory authority requires more), Selorah will make available information necessary to demonstrate compliance with this DPA, which may include security summaries or third-party audit reports. On-site audits require mutual agreement on scope, timing, and confidentiality, and costs may be allocated to the requesting Controller if an audit exceeds standard diligence.`})]}),(0,r.jsxs)(`section`,{className:`mb-12`,children:[(0,r.jsx)(`h2`,{className:`text-2xl font-bold text-gray-900 mb-4`,children:`14. Liability, Precedence, and Contact`}),(0,r.jsx)(`p`,{className:`text-gray-600 mb-4`,children:`Liability under this DPA is subject to the limitations in the main commercial agreement between the parties, except where prohibited by law. If there is a conflict between this DPA and other terms regarding data protection, this DPA prevails for Processing under Controller instructions.`}),(0,r.jsx)(`p`,{className:`text-gray-600`,children:`Contact for DPA notices: legal@selorah.health and privacy@selorah.health — Selorah Health Limited.`})]})]})}export{i as default};